lock table public.world_characters in access exclusive mode;
insert into public.world_map_regions(region_id, territory_id, territory_name, region_name, region_type, danger_level, min_level, description, travel_from, gather_nodes, faction_control, is_starting_area, active, world_x, world_y, elevation, terrain_cost, rest_spot_type, rest_spot_name, rest_quality, rest_fee, rest_risk, is_safe_zone, has_stable, contested, home_faction_id, control_faction_id)
select x.region_id, x.territory_id, x.territory_name, x.region_name, x.region_type, x.danger_level, x.min_level, x.description, array(select jsonb_array_elements_text(x.travel_from)), '{}'::text[], x.faction_control, false, true, x.world_x, x.world_y, x.elevation, x.terrain_cost, x.rest_spot_type, x.rest_spot_name, x.rest_quality, x.rest_fee, x.rest_risk, x.is_safe_zone, false, false, x.home_faction_id, x.control_faction_id from jsonb_to_recordset($J$[{"region_id":"lotus_sewer","territory_id":"underworld","territory_name":"흑련 지하회랑","region_name":"연등 하수도","region_type":"underground","danger_level":5,"min_level":7,"description":"도성 아래로 흐르는 큰 하수도. 흑련회 뱃사공들이 연꽃 등을 물에 띄워 밀수 뱃길을 표시한다.","travel_from":["lamp_alley","burial_steps","under_root"],"faction_control":"흑련회","world_x":515,"world_y":478,"elevation":-2,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"home_faction_id":"black_lotus","control_faction_id":"black_lotus"},{"region_id":"ledger_cellar","territory_id":"underworld","territory_name":"흑련 지하회랑","region_name":"흑련 장부고","region_type":"underground","danger_level":8,"min_level":18,"description":"흑련회가 맡아 둔 이름을 장부로 지키는 지하 서고. 장부에서 새어 나온 이름들이 서가 사이를 떠돈다.","travel_from":["hidden_bazaar","under_root"],"faction_control":"흑련회","world_x":440,"world_y":600,"elevation":-4,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"home_faction_id":"black_lotus","control_faction_id":"black_lotus"},{"region_id":"frost_pine_pass","territory_id":"north","territory_name":"북령 맹약지","region_name":"서리솔 고개","region_type":"mountain_pass","danger_level":5,"min_level":8,"description":"서리 앉은 소나무가 빽빽한 고개. 북령맹 나무꾼과 숯꾼들이 겨울 땔감을 지고 넘는다.","travel_from":["snow_hollow","frost_valley"],"faction_control":"북령맹","world_x":378,"world_y":180,"elevation":3,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"home_faction_id":"north_league","control_faction_id":"north_league"},{"region_id":"old_glacier","territory_id":"north","territory_name":"북령 맹약지","region_name":"천년 빙하","region_type":"ice_valley","danger_level":9,"min_level":27,"description":"북녘 끝에 천 년 동안 녹지 않은 얼음 벌판. 얼음 속에 옛 넋과 짐승들이 그대로 갇혀 있다.","travel_from":["sky_lake","thunder_peak"],"faction_control":"북령맹","world_x":530,"world_y":45,"elevation":6,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"home_faction_id":"north_league","control_faction_id":"north_league"},{"region_id":"patrol_office","territory_id":"capital","territory_name":"야행국 직할령","region_name":"옛 순라청","region_type":"ruins","danger_level":7,"min_level":12,"description":"도성의 밤 순라를 맡던 관청 터. 관청이 문을 닫았는데도 순라 등불을 든 넋들이 밤마다 골목을 돈다.","travel_from":["ghost_bamboo","old_prison","hidden_bazaar"],"faction_control":"야행국 정통파","world_x":378,"world_y":478,"elevation":0,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"home_faction_id":"night_office","control_faction_id":"night_office"},{"region_id":"blood_dunes","territory_id":"frontier","territory_name":"적월 교령","region_name":"핏빛 모래바다","region_type":"desert","danger_level":8,"min_level":17,"description":"붉은 모래언덕이 바다처럼 끝없이 이어진 서쪽 끝. 바람이 불 때마다 모래 밑에서 옛 대상의 짐이 드러난다.","travel_from":["glass_canyon","crimson_altar"],"faction_control":"적월교","world_x":70,"world_y":295,"elevation":0,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"home_faction_id":"red_moon_cult","control_faction_id":"red_moon_cult"},{"region_id":"sleeping_port","territory_id":"east","territory_name":"수향 연맹령","region_name":"잠든 포구","region_type":"coast","danger_level":8,"min_level":19,"description":"수향연맹이 바다 무역을 하던 옛 포구. 물안개 속에 닻을 내린 배들이 주인 없이 잠들어 있다.","travel_from":["sunken_palace","tide_gate"],"faction_control":"수향연맹","world_x":925,"world_y":240,"elevation":0,"terrain_cost":1,"rest_spot_type":"field_camp","rest_spot_name":"임시 야영지","rest_quality":1,"rest_fee":2,"rest_risk":30,"is_safe_zone":false,"home_faction_id":"river_alliance","control_faction_id":"river_alliance"}]$J$::jsonb) as x(region_id text, territory_id text, territory_name text, region_name text, region_type text, danger_level int, min_level int, description text, travel_from jsonb, gather_nodes jsonb, faction_control text, is_starting_area boolean, active boolean, world_x int, world_y int, elevation int, terrain_cost numeric, rest_spot_type text, rest_spot_name text, rest_quality int, rest_fee int, rest_risk int, is_safe_zone boolean, has_stable boolean, contested boolean, home_faction_id text, control_faction_id text)
on conflict (region_id) do update set territory_id = excluded.territory_id, territory_name = excluded.territory_name, region_name = excluded.region_name, region_type = excluded.region_type, danger_level = excluded.danger_level, min_level = excluded.min_level, description = excluded.description, travel_from = excluded.travel_from, faction_control = excluded.faction_control, world_x = excluded.world_x, world_y = excluded.world_y, elevation = excluded.elevation, active = excluded.active, home_faction_id = excluded.home_faction_id, control_faction_id = excluded.control_faction_id;
insert into public.world_region_theme(region_id, theme)
select x.region_id, x.theme from jsonb_to_recordset($J$[{"region_id":"lotus_sewer","theme":"deep"},{"region_id":"ledger_cellar","theme":"deep"},{"region_id":"frost_pine_pass","theme":"mountain"},{"region_id":"old_glacier","theme":"mountain"},{"region_id":"patrol_office","theme":"city"},{"region_id":"blood_dunes","theme":"desert"},{"region_id":"sleeping_port","theme":"water"}]$J$::jsonb) as x(region_id text, theme text)
