insert into public.world_region_profiles(region_id, biome_key, biome_name, faction_style, signature_clue, signature_event, signature_items, survival_hazard, visual_identity, signature_resources, investigation_reward)
select x.region_id, x.biome_key, x.biome_name, x.faction_style, x.signature_clue, x.signature_event, array(select jsonb_array_elements_text(x.signature_items)), x.survival_hazard, x.visual_identity, array(select jsonb_array_elements_text(x.signature_resources)), x.investigation_reward from jsonb_to_recordset($J$[{"region_id":"lotus_sewer","biome_key":"deep","biome_name":"지하·물길","faction_style":"흑련회 뱃사공·하수의 짐승","signature_clue":"연등 하수도의 부표: 갈대로 엮은 부표마다 흑련회 연꽃이 새겨져 있다.","signature_event":"연등 하수도 고유 사건: 꺼진 연등을 모두 다시 띄우면 흑련회 밀수 뱃길의 끝이 드러난다.","signature_items":["lantern_oil","shadow_fang","spirit_dust"],"survival_hazard":"익사·독·어둠","visual_identity":"물에 뜬 연꽃 등, 기름 번진 둑길, 거룻배","signature_resources":["drowned_scale","frost_salt","ghost_ash","herb","lantern_oil","river_reed","shadow_fang","silk","spirit_dust","tonic","travel_ration"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"ledger_cellar","biome_key":"deep","biome_name":"지하·서고","faction_style":"흑련회 장부지기·새어 나온 이름","signature_clue":"흑련 장부고의 장부: 이름 옆마다 맡긴 날짜와 부르는 호칭이 함께 적혀 있다.","signature_event":"흑련 장부고 고유 사건: 찢긴 장부를 다시 묶으면 가장 오래된 장부에 누가 이름을 맡겼는지 드러난다.","signature_items":["lantern_oil","tonic","travel_ration"],"survival_hazard":"침식·결계·어둠","visual_identity":"끝없는 서가, 금줄 둘린 빗장, 먹 냄새","signature_resources":["fine_paper","ghost_ash","herb","inkstone","lantern_oil","mirror_shard","seal_paper","sealing_ink","spirit_dust","talisman_thread","tonic","travel_ration","ward_fragment"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"frost_pine_pass","biome_key":"mountain","biome_name":"산악·솔숲","faction_style":"북령맹 숯꾼·나무꾼","signature_clue":"서리솔 고개의 숯가마: 가마마다 숯을 구운 날과 숯꾼의 이름이 새겨져 있다.","signature_event":"서리솔 고개 고유 사건: 꺼진 숯가마에 다시 불을 넣으면 고개를 넘다 사라진 숯꾼의 이야기가 드러난다.","signature_items":["frost_salt","beast_hide","travel_ration"],"survival_hazard":"추위·매복·눈보라","visual_identity":"서리 앉은 소나무, 숯막, 눈 덮인 벌목 터","signature_resources":["beast_hide","charcoal","frost_salt","herb","medicine_base","moon_moss","resin","travel_ration","wood"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"old_glacier","biome_key":"mountain","biome_name":"산악·빙원","faction_style":"북령맹 빙하 순찰꾼·얼음에 갇힌 넋","signature_clue":"천년 빙하의 얼음 경문: 얼음 벽에 누군가 천 년 전 글자로 경문을 새겨 두었다.","signature_event":"천년 빙하 고유 사건: 얼음 거인을 다시 잠재우면 얼음 속 옛 마을이 왜 얼어붙었는지 드러난다.","signature_items":["monster_core","spirit_glass","spirit_dust"],"survival_hazard":"추위·낙빙·침식","visual_identity":"푸른 얼음 벽, 크레바스, 얼음에 갇힌 그림자","signature_resources":["drowned_scale","frost_salt","ghost_ash","jade_shard","monster_core","ore","raw_iron","spirit_dust","spirit_glass","thunder_ore"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"patrol_office","biome_key":"city","biome_name":"도성·관청","faction_style":"정통파 옛 순라군·순라 등불 넋","signature_clue":"옛 순라청의 순라 일지: 마지막 장에 순라를 마친 시각이 적혀 있지 않다.","signature_event":"옛 순라청 고유 사건: 마지막 순라 일지를 채우면 순라청이 문을 닫은 밤의 일이 드러난다.","signature_items":["steel_ingot","raw_iron","ore"],"survival_hazard":"침식·결계·매복","visual_identity":"무너진 관청 대문, 순라 등불, 방울 금줄","signature_resources":["charcoal","herb","inkstone","ore","raw_iron","seal_paper","sealing_ink","steel_ingot","talisman_thread","tonic","travel_ration"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"blood_dunes","biome_key":"desert","biome_name":"황무지·사막","faction_style":"적월교를 떠난 길잡이·사라진 대상","signature_clue":"핏빛 모래바다의 돌무덤: 돌마다 모래에 묻힌 대상의 이름이 붉은 글씨로 적혀 있다.","signature_event":"핏빛 모래바다 고유 사건: 붉은 신기루를 걷어 내면 사라진 대상이 마지막으로 향한 곳이 드러난다.","signature_items":["ember_crystal","ward_fragment","spirit_dust"],"survival_hazard":"갈증·독·신기루","visual_identity":"붉은 모래언덕, 낙타 뼈, 붉은 소금 바닥","signature_resources":["cinnabar","ember_crystal","ghost_ash","herb","herbal_extract","jade_shard","medicine_base","ore","spirit_dust","ward_fragment"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"},{"region_id":"sleeping_port","biome_key":"water","biome_name":"물가·바다","faction_style":"수향연맹 옛 선주·잠든 배의 넋","signature_clue":"잠든 포구의 무역 장부: 마지막 무역선이 떠난 날 옆에 「돌아오지 않음」이라고만 적혀 있다.","signature_event":"잠든 포구 고유 사건: 물귀 선장을 풀어 주면 수향연맹의 옛 바닷길이 드러난다.","signature_items":["lantern_oil","tonic","travel_ration"],"survival_hazard":"익사·안개·밀물","visual_identity":"닻 내린 무역선, 물안개, 부서진 등대","signature_resources":["drowned_scale","herb","jade_shard","lantern_oil","lumber","reinforced_lumber","resin","river_reed","tonic","travel_ration","wood"],"investigation_reward":"그 지역의 옛 기록과 세력의 흔적"}]$J$::jsonb) as x(region_id text, biome_key text, biome_name text, faction_style text, signature_clue text, signature_event text, signature_items jsonb, survival_hazard text, visual_identity text, signature_resources jsonb, investigation_reward text)
on conflict (region_id) do update set biome_name = excluded.biome_name, faction_style = excluded.faction_style, signature_clue = excluded.signature_clue, signature_event = excluded.signature_event, signature_items = excluded.signature_items, survival_hazard = excluded.survival_hazard, visual_identity = excluded.visual_identity, signature_resources = excluded.signature_resources;
insert into public.world_region_lore(region_id, lines)
select x.region_id, x.lines from jsonb_to_recordset($J$[{"region_id":"lotus_sewer","lines":[{"s":null,"t":"연등 하수도. 도성 아래를 흐르는 큰 하수도입니다. 흑련회 뱃사공들은 물 위에 연꽃 등을 띄워 길을 표시합니다."},{"s":null,"t":"등 하나가 꺼지면 그 물길은 아무도 지나가지 않습니다. 뱃사공들은 꺼진 등 아래에 무엇이 있는지 묻지 않습니다."}]},{"region_id":"ledger_cellar","lines":[{"s":null,"t":"흑련 장부고. 흑련회가 맡아 둔 이름을 장부로 지키는 지하 서고입니다. 회원들은 이곳에 이름을 맡기고 호칭으로 불립니다."},{"s":null,"t":"서가 사이에서 누군가 제 이름을 부르는 소리가 납니다. 장부 틈으로 새어 나온 이름들입니다."}]},{"region_id":"frost_pine_pass","lines":[{"s":null,"t":"서리솔 고개. 서리 앉은 소나무가 빽빽한 고개입니다. 북령맹 나무꾼과 숯꾼들이 겨울 땔감을 지고 이 길을 넘습니다."},{"s":null,"t":"고개 아래 숯가마 몇 개가 차갑게 식어 있습니다. 숯꾼들은 요즘 고개에 오르기를 꺼립니다."}]},{"region_id":"old_glacier","lines":[{"s":null,"t":"천년 빙하. 북녘 끝에 천 년 동안 녹지 않은 얼음 벌판입니다. 푸른 얼음 속에 사람과 짐승의 그림자가 그대로 갇혀 있습니다."},{"s":null,"t":"요즘 빙하 끝자락이 조금씩 녹고 있습니다. 북령맹 순찰꾼들은 얼음 속 그림자가 움직이는 것을 보았다고 합니다."}]},{"region_id":"patrol_office","lines":[{"s":null,"t":"옛 순라청. 도성의 밤 순라를 맡던 관청 터입니다. 관청이 문을 닫은 지 오래인데 처마 끝에 순라 등불이 아직 걸려 있습니다."},{"s":null,"t":"통금 북이 울리던 시각이 되면 골목에 방울 소리가 납니다. 순라를 마치지 못한 이들이 아직 돌고 있습니다."}]},{"region_id":"blood_dunes","lines":[{"s":null,"t":"핏빛 모래바다. 붉은 모래언덕이 바다처럼 끝없이 이어진 서쪽 끝입니다. 바람이 불 때마다 모래 밑에서 옛 대상의 짐이 드러납니다."},{"s":null,"t":"어귀의 돌무덤마다 이름이 적혀 있습니다. 모래바다를 건너다 돌아오지 못한 이들의 이름입니다."}]},{"region_id":"sleeping_port","lines":[{"s":null,"t":"잠든 포구. 수향연맹이 바다 무역을 하던 옛 포구입니다. 물안개 속에 닻을 내린 배들이 주인 없이 잠들어 있습니다."},{"s":null,"t":"안개가 짙은 날에는 포구 끝 등대에 불이 켜집니다. 등대지기가 떠난 지 스무 해가 넘었는데도 그렇습니다."}]}]$J$::jsonb) as x(region_id text, lines jsonb)
on conflict (region_id) do update set lines = excluded.lines;
insert into public.world_exploration_nodes(node_id, region_id, parent_node_id, hierarchy_level, node_name, description, min_level, sort_order)
