"},{"monster_id":"r220_dune_4","region_id":"blood_dunes","monster_name":"핏빛 등딱지 게","monster_type":"갑각 요괴","min_level":19,"max_level":23,"hp":2550,"attack_power":128,"spawn_weight":15,"description":"붉은 소금 바닥에 사는 커다란 게. 등딱지가 주사 광물처럼 붉고 단단하다.","drops":{"cinnabar":3,"jade_shard":1},"difficulty_rank":5,"mechanic_key":"armored","mechanic_description":"껍질이 단단하다. 방어를 무시하는 공격이나 술법이 낫다.","role":"main","kind":"shell"},{"monster_id":"r220_dune_5","region_id":"blood_dunes","monster_name":"붉은 신기루","monster_type":"지역 우두머리","min_level":17,"max_level":19,"hp":462,"attack_power":37,"spawn_weight":12,"description":"모래바다 한가운데 서는 붉은 신기루가 요괴가 되었다. 길손을 홀려 모래 속으로 데려간다.","drops":{"ember_crystal":1,"cinnabar":3,"spirit_dust":3},"difficulty_rank":10,"mechanic_key":"boss","mechanic_description":"보스급 위협. 세 번째 행동마다 광역급 강공격을 하므로 방어 태세를 섞어라.","role":"guardian","kind":"sky"},{"monster_id":"r220_port_1","region_id":"sleeping_port","monster_name":"잠든 배 물귀","monster_type":"물귀신","min_level":19,"max_level":22,"hp":336,"attack_power":29,"spawn_weight":14,"description":"닻 내린 배 밑에 매달린 물귀신. 배에 오르는 사람의 발목을 끌어내린다.","drops":{"drowned_scale":1,"river_reed":1},"difficulty_rank":2,"mechanic_key":"tide","mechanic_description":"물살로 끌어당겨 발을 묶는다. 거리를 두고 싸우거나 묶이기 전에 끊어라.","role":"common","kind":"water"},{"monster_id":"r220_port_2","region_id":"sleeping_port","monster_name":"안개 갈매기 떼","monster_type":"날짐승 요괴","min_level":19,"max_level":22,"hp":336,"attack_power":29,"spawn_weight":14,"description":"물안개 속에서 한꺼번에 날아드는 갈매기 떼. 부리가 쇠처럼 단단하다.","drops":{"beast_bone":1,"beast_fang":1},"difficulty_rank":2,"mechanic_key":"aerial","mechanic_description":"하늘에서 내리꽂는다. 원거리 사격이 잘 듣는다.","role":"common","kind":"bird"},{"monster_id":"r220_port_3","region_id":"sleeping_port","monster_name":"따개비 집게귀","monster_type":"갑각 요괴","min_level":21,"max_level":25,"hp":2850,"attack_power":142,"spawn_weight":15,"description":"온몸에 따개비를 뒤집어쓴 커다란 집게 요괴. 무역선 밑창을 집게로 뜯는다.","drops":{"drowned_scale":3,"jade_shard":1,"frost_salt":2},"difficulty_rank":5,"mechanic_key":"armored","mechanic_description":"껍질이 단단하다. 방어를 무시하는 공격이나 술법이 낫다.","role":"main","kind":"shell"},{"monster_id":"r220_port_4","region_id":"sleeping_port","monster_name":"물안개 거울","monster_type":"거울 요괴","min_level":21,"max_level":25,"hp":2850,"attack_power":142,"spawn_weight":15,"description":"물안개가 거울처럼 굳은 요괴. 비친 사람의 공격을 되돌린다.","drops":{"spirit_glass":1,"mirror_shard":1,"drowned_scale":2},"difficulty_rank":5,"mechanic_key":"reflect","mechanic_description":"공격의 일부를 되돌린다. 원거리 사격이나 봉인 제압을 써라.","role":"main","kind":"mirror"},{"monster_id":"r220_port_5","region_id":"sleeping_port","monster_name":"포구를 삼킨 물귀 선장","monster_type":"지역 우두머리","min_level":19,"max_level":21,"hp":504,"attack_power":40,"spawn_weight":12,"description":"마지막 무역선과 함께 가라앉은 선장의 넋. 포구를 떠나려는 배를 모두 붙잡아 둔다.","drops":{"lantern_oil":2,"drowned_scale":3,"jade_shard":1},"difficulty_rank":10,"mechanic_key":"boss","mechanic_description":"보스급 위협. 세 번째 행동마다 광역급 강공격을 하므로 방어 태세를 섞어라.","role":"guardian","kind":"water"}]$J$::jsonb) as x(monster_id text, region_id text, monster_name text, monster_type text, min_level int, max_level int, hp int, attack_power int, spawn_weight int, description text, drops jsonb, difficulty_rank int, mechanic_key text, mechanic_description text, role text, kind text)
