as x(site_id text, region_id text, site_name text, site_type text, bonus_item text, loot_table jsonb, rare_bonus jsonb, description text, bonus_chance int, loot_category text, loot_categories jsonb, active boolean)
on conflict (site_id) do update set site_name = excluded.site_name, loot_table = excluded.loot_table, rare_bonus = excluded.rare_bonus, active = excluded.active;
insert into public.world_gathering_discoveries(owner_id, spot_id)
select c.owner_id, gs.spot_id from public.world_characters c
  cross join public.world_gathering_spots gs join public.world_exploration_nodes n on n.node_id = gs.node_id and n.hierarchy_level = 1 and n.region_id in ('lotus_sewer', 'ledger_cellar', 'frost_pine_pass', 'old_glacier', 'patrol_office', 'blood_dunes', 'sleeping_port')
on conflict do nothing;
insert into public.world_quest_npcs(npc_key, npc_name, bio)
select x.npc_key, x.npc_name, x.bio from jsonb_to_recordset($J$[{"npc_key":"q:r220_nodeul","npc_name":"뱃사공 노들","bio":"연등 하수도에서 거룻배를 미는 흑련회 뱃사공. 물길마다 연등을 띄우고 거두는 일을 마흔 해 넘게 했다."},{"npc_key":"q:r220_sodam","npc_name":"장부지기 소담","bio":"흑련 장부고를 지키는 장부지기. 본명은 장부에 맡겨 두었고 「소담」은 회에서 부르는 호칭이다."},{"npc_key":"q:r220_deokbo","npc_name":"숯꾼 덕보","bio":"서리솔 고개 아래 숯막에서 숯을 굽는 북령맹 숯꾼. 고개를 넘는 나무꾼들에게 늘 숯불을 나눠 준다."},{"npc_key":"q:r220_hanseol","npc_name":"빙하지기 한설","bio":"천년 빙하를 도는 북령맹 순찰꾼. 얼음이 녹는 소리만 듣고도 어디가 갈라질지 안다."},{"npc_key":"q:r220_dolsoe","npc_name":"순라군 돌쇠","bio":"옛 순라청의 마지막 순라군. 관청이 문을 닫은 뒤에도 순라 등불을 손질하며 관청 터를 지킨다."},{"npc_key":"q:r220_barami","npc_name":"길잡이 바람이","bio":"적월교를 떠나 핏빛 모래바다의 길잡이가 된 여인. 모래 위 바람결만 보고 길을 찾는다."},{"npc_key":"q:r220_gyewol","npc_name":"선주 계월","bio":"잠든 포구에서 무역선을 부리던 수향연맹 선주 집안의 딸. 아버지의 배가 돌아오기를 기다리며 포구를 떠나지 않는다."}]$J$::jsonb) as x(npc_key text, npc_name text, bio text)
on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, sort, epilogue, active)
select x.quest_id, 'side', x.cat, x.title, x.summary, x.region_id, x.min_level, array(select jsonb_array_elements_text(x.after)), x.sort, x.epilogue, true from jsonb_to_recordset($J$[{"quest_id":"rq_lotus_sewer","cat":"전투·하수도","title":"꺼지는 연등","summary":"연등 하수도의 물길마다 연꽃 등이 하나둘 꺼진다. 늙은 뱃사공 노들은 등이 꺼진 물길로 배를 낼 수 없다고 한다.","region_id":"lotus_sewer","min_level":7,"after":[],"sort":1400,"epilogue":[]},{"quest_id":"rq_ledger_cellar","cat":"조사·장부고","title":"새어 나온 이름","summary":"흑련 장부고의 장부에서 맡겨 둔 이름들이 새어 나온다. 장부지기 소담은 이름이 주인을 찾아 떠돌기 전에 장부를 다시 묶어야 한다고 한다.","region_id":"ledger_cellar","min_level":18,"after":[],"sort":1401,"epilogue":[]},{"quest_id":"rq_frost_pine_pass","cat":"채집·서리솔","title":"식어 버린 숯가마","summary":"서리솔 고개 아래 숯가마가 하나둘 식어 간다. 숯꾼 덕보는 나무꾼들이 고개에 오르지 못해 땔감이 끊겼다고 한다.","region_id":"frost_pine_pass","min_level":8,"after":[],"sort":1402,"epilogue":[]},{"quest_id":"rq_old_glacier","cat":"전투·빙하","title":"녹아내리는 얼음","summary":"천 년 동안 녹지 않던 빙하 끝자락이 녹기 시작했다. 빙하지기 한설은 얼음 속에 갇혀 있던 것들이 깨어나고 있다고 한다.","region_id":"old_glacier","min_level":27,"after":[],"sort":1403,"epilogue":[]},{"quest_id":"rq_patrol_office","cat":"조사·순라청","title":"끝나지 않은 순라","summary":"문 닫은 옛 순라청 골목에서 밤마다 방울 소리가 난다. 마지막 순라군 돌쇠는 순라를 마치지 못한 이들이 아직 돌고 있다고 한다.","region_id":"patrol_office","min_level":12,"after":[],"sort":1404,"epilogue":[]},{"quest_id":"rq_blood_dunes","cat":"전투·모래바다","title":"모래에 묻힌 대상","summary":"핏빛 모래바다에서 대상 하나가 통째로 사라졌다. 길잡이 바람이는 붉은 신기루가 그들을 모래 속으로 데려갔다고 믿는다.","region_id":"blood_dunes","min_level":17,"after":[],"sort":1405,"epilogue":[]},{"quest_id":"rq_sleeping_port","cat":"조사·포구","title":"안개 속 무역선","summary":"잠든 포구의 배들은 닻을 올려도 바다로 나가지 못한다. 선주 계월은 마지막 무역선과 함께 가라앉은 선장이 배들을 붙잡고 있다고 한다.","region_id":"sleeping_port","min_level":19,"after":[],"sort":1406,"epilogue":[]}]$J$::jsonb) as x(quest_id text, kind text, cat text, title text, summary text, region_id text, min_level int, after jsonb, sort int, epilogue jsonb, active boolean)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, epilogue = excluded.epilogue, active = excluded.active;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward)
select x.quest_id, x.step, x.title, x.goal, x.need, x.lines, x.reward from jsonb_to_recordset($J$[{"quest_id":"rq_lotus_sewer","step":1,"title":"물길 위의 등","goal":"연등 하수도에서 뱃사공 노들을 만난다","need":{"at":["lotus_sewer"]},"lines":[{"s":null,"t":"하수도 쇠문을 지나자 물 위에 연꽃 모양의 등이 줄지어 떠 있었다. 그 가운데 절반은 불이 꺼져 있었다."},{"s":null,"t":"거룻배 한 척이 둑에 닿았다. 허리가 굽은 뱃사공이 장대를 세우고 꺼진 등을 하나 건져 올렸다."},{"s":"q:r220_nodeul","t":"또 꺼졌구먼. 오늘만 일곱 개째요."},{"s":null,"t":"나는 등이 왜 꺼지는지 물었다. 노인이 건진 등의 밑동을 내 쪽으로 돌려 보였다. 갈대로 엮은 부표가 이빨 자국투성이였다."},{"s":"q:r220_nodeul","t":"쥐 떼가 부표를 갉아 먹소. 부표가 가라앉으면 등도 물에 잠기지. 등이 꺼진 물길로는 배를 낼 수가 없소."},{"s":"q:r220_nodeul","t":"나는 노들이라 하오. 손님, 하수 쥐 떼를 세 번만 쫓아 주시오. 쥐들이 물길을 따라 몰려다니니 금방 만날 거요."}],"reward":{}},{"quest_id":"rq_lotus_sewer","step":2,"title":"하수 쥐 떼","goal":"하수 쥐 떼를 3번 쓰러뜨린다","need":{"at":["lotus_sewer"],"tasks":[{"t":"win","m":["r220_sewer_1"],"n":3}]},"lines":[{"s":null,"t":"쥐 떼가 흩어지자 둑길에 갉다 만 갈대 부표가 수북이 남았다. 노들이 장대 끝으로 부표를 하나씩 뒤집어 보았다."},{"s":"q:r220_nodeul","t":"고맙소. 이제 새로 띄울 부표가 있어야 하는데, 갈대가 모자라오."},{"s":null,"t":"노인이 빈 갈대 묶음을 털어 보이고는 물가 쪽을 턱으로 가리켰다."},{"s":"q:r220_nodeul","t":"물길 굽이에 수향 갈대가 자라오. 세 줌만 베어다 주시오. 부표는 내가 엮겠소."}],"reward":{"xp":171}},{"quest_id":"rq_lotus_sewer","step":3,"title":"새 부표","goal":"연등 하수도에서 수향 갈대 3개를 거둬 노들에게 건넨다","need":{"at":["lotus_sewer"],"tasks":[{"t":"gather","items":["river_reed"],"r":["lotus_sewer"],"n":3}],"give":{"river_reed":3}},"lines":[{"s":null,"t":"내가 갈대를 건네자 노들은 배 위에 앉아 부표를 엮기 시작했다. 거친 손이 갈대를 세 번 꼬아 단단히 묶었다."},{"s":"q:r220_nodeul","t":"이렇게 엮으면 쥐가 갉아도 쉽게 안 가라앉소."},{"s":null,"t":"부표를 다 엮은 노인이 연등을 얹어 물에 띄웠다. 등은 잠깐 밝게 타오르더니 하수도 깊은 쪽에서 불어온 바람에 다시 꺼졌다."},{"s":"q:r220_nodeul","t":"…저 아래 늙은 자라가 숨을 쉬었구먼. 그놈이 숨을 내쉬면 물길의 등이 한꺼번에 꺼지오."},{"s":"q:r220_nodeul","t":"맨 아래 물웅덩이까지 내려가 하수 늙은 자라를 잠재워 주시오. 그래야 등이 다시 버티오."}],"reward":{"xp":171}},{"quest_id":"rq_lotus_sewer","step":4,"title":"늙은 자라","goal":"하수 늙은 자라를 쓰러뜨린다","need":{"at":["lotus_sewer"],"tasks":[{"t":"win","m":["r220_sewer_5"],"n":1}]},"lines":[{"s":null,"t":"늙은 자라가 물웅덩이 바닥으로 가라앉자 하수도 안의 바람이 멎었다. 둑으로 돌아오니 노들이 새 부표에 등을 얹고 있었다."},{"s":null,"t":"노인이 등에 하나씩 불을 붙였다. 이번에는 등이 꺼지지 않고 물길을 따라 천천히 흘러갔다."},{"s":"q:r220_nodeul","t":"저 등들이 물길 끝까지 가면 밀수 배가 다시 다닐 수 있소. 흑련회 사람들은 등이 떠 있는 길로만 다니니까."},{"s":null,"t":"나는 등이 꺼진 물길에는 무엇이 있느냐고 물었다. 노인은 대답 대신 장대를 물에 꽂았다."},{"s":"q:r220_nodeul","t":"그건 묻지 않는 게 이 물길의 법이오. 손님 덕에 오늘 밤은 배를 낼 수 있겠구려."}],"reward":{"xp":171,"gil":33,"items":{"tonic":2,"travel_ration":1,"river_reed":2}}},{"quest_id":"rq_ledger_cellar","step":1,"title":"호칭으로 부르는 문","goal":"흑련 장부고에서 장부지기 소담을 만난다","need":{"at":["ledger_cellar"]},"lines":[{"s":null,"t":"돌계단을 내려가자 먹 냄새가 짙어졌다. 문간에 앉은 여인이 등잔을 들어 내 얼굴을 비추었다."},{"s":"q:r220_sodam","t":"이름은 묻지 않겠습니다. 이곳에서는 호칭으로만 부르니까요. 저는 소담이라고 불립니다."},{"s":null,"t":"소담이 서가 쪽을 돌아보았다. 어둠 속에서 누군가 제 이름을 부르는 소리가 작게 들렸다."},{"s":"q:r220_sodam","t":"회원들이 맡긴 이름이 장부에서 새어 나오고 있습니다. 새어 나온 이름은 주인을 찾아 서가 사이를 떠돌아요."},{"s":null,"t":"나는 이름이 주인에게 돌아가면 안 되느냐고 물었다. 소담은 고개를 저었다."},{"s":"q:r220_sodam","t":"맡긴 이름은 맡긴 사람이 찾으러 와야 돌려줍니다. 그 전에 밖으로 나가면 아무도 그 이름을 지켜 주지 못해요. 장부에서 샌 이름을 네 번만 붙잡아 주세요."}],"reward":{}},{"quest_id":"rq_ledger_cellar","step":2,"title":"떠도는 이름","goal":"장부에서 샌 이름을 4번 쓰러뜨린다","need":{"at":["ledger_cellar"],"tasks":[{"t":"win","m":["r220_ledger_1"],"n":4}]},"lines":[{"s":null,"t":"붙잡힌 이름들이 종이 조각이 되어 바닥에 흩어졌다. 소담이 무릎을 꿇고 조각을 하나씩 주워 장부 사이에 끼웠다."},{"s":"q:r220_sodam","t":"이 이름들은 장부로 돌아왔습니다. 그런데 장부가 이렇게 찢겨 있으면 또 샐 거예요."},{"s":null,"t":"소담이 찢어진 장부 한 권을 들어 보였다. 묶은 끈이 끊어지고 종이 가장자리가 검게 번져 있었다."},{"s":"q:r220_sodam","t":"장부를 다시 묶으려면 봉인 먹이 필요합니다. 서가 안쪽 문서 더미에서 봉인 먹 세 개만 거둬다 주시겠어요?"}],"reward":{"xp":758}},{"quest_id":"rq_ledger_cellar","step":3,"title":"봉인 먹","goal":"흑련 장부고에서 봉인 먹 3개를 거둬 소담에게 건넨다","need":{"at":["ledger_cellar"],"tasks":[{"t":"gather","items":["sealing_ink"],"r":["ledger_cellar"],"n":3}],"give":{"sealing_ink":3}},"lines":[{"s":null,"t":"내가 봉인 먹을 건네자 소담은 붓에 먹을 듬뿍 찍어 장부의 묶음 자리에 둘렀다. 먹이 마르자 찢어진 종이가 다시 붙었다."},{"s":"q:r220_sodam","t":"이 정도면 한동안은 버틸 겁니다. 문제는 맨 밑 금고예요."},{"s":null,"t":"소담이 등잔을 낮춰 장부고 아래쪽 계단을 비추었다. 계단 끝에서 묵직한 발소리가 울렸다."},{"s":"q:r220_sodam","t":"장부를 쓰고 남은 먹이 쌓여 거인이 되었습니다. 그것이 금고 앞에서 장부를 찢어 이름을 풀어 놓아요."},{"s":"q:r220_sodam","t":"장부고의 먹 거인을 쓰러뜨려 주세요. 가장 오래된 장부가 그 금고에 있습니다."}],"reward":{"xp":758}},{"quest_id":"rq_ledger_cellar","step":4,"title":"먹 거인","goal":"장부고의 먹 거인을 쓰러뜨린다","need":{"at":["ledger_cellar"],"tasks":[{"t":"win","m":["r220_ledger_5"],"n":1}]},"lines":[{"s":null,"t":"먹 거인이 무너지자 바닥에 검은 먹물이 넓게 고였다. 금고 문이 저절로 조금 열렸다."},{"s":null,"t":"소담이 금고 안에서 낡은 장부 한 권을 꺼냈다. 표지에는 이름 대신 「맡긴 이 없음」이라고 적혀 있었다."},{"s":"q:r220_sodam","t":"가장 오래된 장부입니다. 맡긴 사람이 적혀 있지 않아요. 누가 처음 이름을 맡겼는지는 회주님만 아실 거예요."},{"s":null,"t":"나는 그 장부를 펼쳐 보아도 되느냐고 물었다. 소담은 장부를 품에 안고 천천히 고개를 저었다."},{"s":"q:r220_sodam","t":"언젠가 당신이 이 회에 이름을 맡기러 오면 그때 보여 드리지요. 오늘은 고맙습니다. 이름들이 조용해졌어요."}],"reward":{"xp":758,"gil":77,"items":{"tonic":2,"travel_ration":1,"sealing_ink":2}}},{"quest_id":"rq_frost_pine_pass","step":1,"title":"찬 숯막","goal":"서리솔 고개에서 숯꾼 덕보를 만난다","need":{"at":["frost_pine_pass"]},"lines":[{"s":null,"t":"고개 아래 숯막에서 연기가 가늘게 올라왔다. 안에서는 덩치 큰 사내가 다 식은 숯가마 앞에 쪼그려 앉아 손을 비비고 있었다."},{"s":"q:r220_deokbo","t":"어서 들어오시오. 불은 시원찮지만 바람은 막아 주오."},{"s":null,"t":"나는 왜 숯가마가 식어 있는지 물었다. 사내가 문밖의 솔숲을 손가락으로 가리켰다."},{"s":"q:r220_deokbo","t":"나는 덕보라 하오. 요즘 솔가지가 사람처럼 일어나 나무꾼들을 쫓아내오. 나무를 못 하니 숯도 못 굽지."},{"s":"q:r220_deokbo","t":"고개 오솔길의 서리솔 정령을 세 번만 쫓아 주시오. 그래야 나무꾼들이 다시 올라가오."}],"reward":{}},{"quest_id":"rq_frost_pine_pass","step":2,"title":"일어선 솔가지","goal":"서리솔 정령을 3번 쓰러뜨린다","need":{"at":["frost_pine_pass"],"tasks":[{"t":"win","m":["r220_pine_1"],"n":3}]},"lines":[{"s":null,"t":"정령들이 쓰러지자 솔가지가 바닥에 흩어졌다. 숯막으로 돌아가니 덕보가 문간에서 나를 기다리고 있었다."},{"s":"q:r220_deokbo","t":"나무꾼들이 오늘 오후에 오르겠다고 하오. 그런데 가마에 불을 붙이려면 송진이 있어야 하오."},{"s":null,"t":"덕보가 빈 송진 단지를 들어 흔들었다. 단지 바닥에 굳은 송진 부스러기만 붙어 있었다."},{"s":"q:r220_deokbo","t":"송진 흐르는 비탈에서 부적목 수지를 세 덩이만 거둬다 주시오. 그걸 불쏘시개로 써야 가마가 살아나오."}],"reward":{"xp":209}},{"quest_id":"rq_frost_pine_pass","step":3,"title":"불쏘시개","goal":"서리솔 고개에서 부적목 수지 3개를 거둬 덕보에게 건넨다","need":{"at":["frost_pine_pass"],"tasks":[{"t":"gather","items":["resin"],"r":["frost_pine_pass"],"n":3}],"give":{"resin":3}},"lines":[{"s":null,"t":"내가 수지를 건네자 덕보는 가마 아궁이에 수지를 넣고 부싯돌을 쳤다. 불길이 확 일어나 숯막 안이 금세 따뜻해졌다."},{"s":"q:r220_deokbo","t":"이제야 숯막 같구먼."},{"s":null,"t":"그때 고갯마루 쪽에서 낮게 우는 소리가 들렸다. 덕보의 얼굴이 굳었다."},{"s":"q:r220_deokbo","t":"산군이오. 서리를 뒤집어쓴 큰 범인데, 그놈이 고갯마루에 버티고 있으니 나무꾼들이 끝까지 못 넘소."},{"s":"q:r220_deokbo","t":"고갯마루의 서리 덮인 산군을 물리쳐 주시오. 그래야 빙혼곡 쪽으로 땔감이 넘어가오."}],"reward":{"xp":209}},{"quest_id":"rq_frost_pine_pass","step":4,"title":"고갯마루의 범","goal":"서리 덮인 산군을 쓰러뜨린다","need":{"at":["frost_pine_pass"],"tasks":[{"t":"win","m":["r220_pine_5"],"n":1}]},"lines":[{"s":null,"t":"산군이 눈밭에 쓰러지자 고갯마루를 덮고 있던 서리가 조금씩 걷혔다. 숯막으로 내려가니 나무꾼들이 나뭇짐을 지고 줄지어 올라가고 있었다."},{"s":null,"t":"덕보가 가마 앞에서 갓 구운 숯을 한 아름 꺼냈다. 검은 숯에서 아직 열기가 올라왔다."},{"s":"q:r220_deokbo","t":"이 숯은 빙혼곡 사람들 몫이오. 겨울을 나려면 숯이 끊기면 안 되니까."},{"s":null,"t":"나는 숯꾼들이 왜 이 고개를 떠나지 않는지 물었다. 덕보가 숯 묻은 손으로 이마를 닦았다."},{"s":"q:r220_deokbo","t":"누군가는 불을 지켜야 하지 않겠소. 북령에서는 그게 숯꾼 몫이오. 고맙소, 덕분에 올겨울도 따뜻하겠구려."}],"reward":{"xp":209,"gil":37,"items":{"tonic":2,"travel_ration":1,"charcoal":2}}},{"quest_id":"rq_old_glacier","step":1,"title":"녹는 소리","goal":"천년 빙하에서 빙하지기 한설을 만난다","need":{"at":["old_glacier"]},"lines":[{"s":null,"t":"얼음 벽 아래에서 물방울 떨어지는 소리가 끊이지 않았다. 털옷을 겹겹이 입은 여인이 얼음 벽에 귀를 대고 서 있었다."},{"s":"q:r220_hanseol","t":"쉿. 들어 보시오. 얼음이 녹는 소리요."},{"s":null,"t":"여인이 귀를 떼고 나를 돌아보았다. 입김이 하얗게 흩어졌다."},{"s":"q:r220_hanseol","t":"나는 한설, 이 빙하를 도는 순찰꾼이오. 천 년 동안 녹지 않던 얼음이 요즘 녹고 있소. 얼음이 녹으면 그 안에 갇혀 있던 넋이 빠져나오지."},{"s":null,"t":"나는 넋이 빠져나오면 어떻게 되느냐고 물었다. 한설이 얼음 벽 속의 그림자를 가리켰다. 그림자 하나가 천천히 고개를 돌렸다."},{"s":"q:r220_hanseol","t":"사람을 얼음 속으로 끌고 들어가오. 얼음에 갇힌 넋을 네 번만 잠재워 주시오. 녹은 자리마다 하나씩 나올 거요."}],"reward":{}},{"quest_id":"rq_old_glacier","step":2,"title":"빠져나온 넋","goal":"얼음에 갇힌 넋을 4번 쓰러뜨린다","need":{"at":["old_glacier"],"tasks":[{"t":"win","m":["r220_glacier_1"],"n":4}]},"lines":[{"s":null,"t":"넋들이 흩어지자 녹은 자리마다 하얀 소금 같은 결정이 남았다. 한설이 결정 하나를 집어 혀끝에 댔다."},{"s":"q:r220_hanseol","t":"빙정염이오. 얼음이 녹을 때 넋이 남긴 것이지."},{"s":null,"t":"